using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild(args[0]);

Console.WriteLine("=== ALL ERRORS ===\n");
var errors = build.FindChildrenRecursive<Error>();
foreach (var error in errors)
{
    var project = error.GetNearestParent<Project>();
    var projectName = project?.Name ?? "unknown";
    Console.WriteLine($"[{projectName}] {error.Code}: {error.Text}");
    if (!string.IsNullOrEmpty(error.File))
        Console.WriteLine($"  File: {error.File}({error.LineNumber},{error.ColumnNumber})");
    Console.WriteLine();
}

Console.WriteLine("\n=== PROJECT BUILD RESULTS ===\n");
var projects = build.FindChildrenRecursive<Project>();
foreach (var p in projects)
{
    Console.WriteLine($"  {p.Name} -> Succeeded={p.Succeeded}");
}

Console.WriteLine("\n=== DEPENDENCY GRAPH (ProjectReferences) ===\n");
var items = build.FindChildrenRecursive<AddItem>().Where(i => i.Name == "ProjectReference");
foreach (var item in items)
{
    var project = item.GetNearestParent<Project>();
    Console.WriteLine($"  {project?.Name} references:");
    foreach (var child in item.Children.OfType<Item>())
    {
        Console.WriteLine($"    -> {child.Text}");
    }
}
EOF
